// 2. 슬라이드 기본 조작

/**
 * 현재 슬라이드에 접근하는 함수
 */
function accessCurrentPresentation() {
  // 현재 활성화된 프레젠테이션 가져오기
  var presentation = SlidesApp.getActivePresentation();

  // 프레젠테이션 정보 로깅
  Logger.log('프레젠테이션 제목: ' + presentation.getName());
  Logger.log('슬라이드 수: ' + presentation.getSlides().length);

  // 현재 선택된 슬라이드 가져오기
  var currentSlide = SlidesApp.getActivePresentation().getSelection().getCurrentPage();
  if (currentSlide) {
    Logger.log('현재 슬라이드 인덱스: ' + (currentSlide.getObjectId()));
  }
}

/**
 * 새 슬라이드 생성하기
 */
function createNewSlide() {
  var presentation = SlidesApp.getActivePresentation();

  // 새 슬라이드 추가 (기본 레이아웃 사용)
  var slide = presentation.appendSlide(SlidesApp.PredefinedLayout.TITLE_AND_BODY);

  // 슬라이드 제목 설정 - 더 안전한 방법으로 접근
  var shapes = slide.getShapes();
  for (var i = 0; i < shapes.length; i++) {
    var shape = shapes[i];
    if (shape.getPlaceholderType() === SlidesApp.PlaceholderType.TITLE) {
      shape.getText().setText('새로운 슬라이드 제목');
    } else if (shape.getPlaceholderType() === SlidesApp.PlaceholderType.BODY) {
      shape.getText().setText('Apps Script로 생성된 슬라이드 내용입니다.');
    }
  }

  // 만약 위 방법으로도 찾지 못했다면 직접 텍스트 상자 추가
  if (shapes.length === 0) {
    slide.insertTextBox('새로운 슬라이드 제목', 100, 50, 400, 50);
    slide.insertTextBox('Apps Script로 생성된 슬라이드 내용입니다.', 100, 150, 400, 200);
  }

  Logger.log('새 슬라이드가 생성되었습니다.');
}

/**
 * 모든 슬라이드의 내용 읽기
 */
function readAllSlideContents() {
  var presentation = SlidesApp.getActivePresentation();
  var slides = presentation.getSlides();

  for (var i = 0; i < slides.length; i++) {
    var slide = slides[i];
    Logger.log('슬라이드 #' + (i + 1));

    // 슬라이드의 모든 텍스트 요소 가져오기
    var shapes = slide.getShapes();
    for (var j = 0; j < shapes.length; j++) {
      var shape = shapes[j];
      if (shape.getText) {
        var text = shape.getText().asString();
        if (text) {
          Logger.log('  텍스트: ' + text);
        }
      }
    }
  }
}

/**
 * 텍스트 상자 생성 및 편집하기
 */
function createAndEditTextbox() {
  var slide = SlidesApp.getActivePresentation().getSelection().getCurrentPage();
  if (!slide) {
    slide = SlidesApp.getActivePresentation().getSlides()[0];
  }

  // 새 텍스트 상자 생성
  var textBox = slide.insertTextBox('이것은 Apps Script로 생성된 텍스트 상자입니다!', 
                                   100, 200, 300, 100);

  // 텍스트 스타일 변경
  var textStyle = textBox.getText().getTextStyle();
  textStyle.setBold(true);
  textStyle.setFontSize(18);
  textStyle.setForegroundColor('#FF0000'); // 빨간색

  // 텍스트 상자 테두리 스타일 변경
  var border = textBox.getBorder();
  border.setDashStyle(SlidesApp.DashStyle.SOLID);
  border.setWeight(2);

  // 테두리 색상 설정 - Line 객체를 통해 설정
  textBox.getBorder().getLineFill().setSolidFill('#0000FF'); // 파란색

  // 배경색 설정
  textBox.getFill().setSolidFill('#FFFFCC'); // 연한 노란색

  Logger.log('텍스트 상자가 생성되고 편집되었습니다.');
}

/**
 * 도형 추가 및 조작하기
 */
function addAndManipulateShape() {
  var slide = SlidesApp.getActivePresentation().getSelection().getCurrentPage();
  if (!slide) {
    slide = SlidesApp.getActivePresentation().getSlides()[0];
  }

  // 원 도형 추가
  var circle = slide.insertShape(SlidesApp.ShapeType.ELLIPSE, 400, 150, 100, 100);
  circle.getFill().setSolidFill('#00FF00'); // 녹색 채우기

  // 사각형 도형 추가
  var rectangle = slide.insertShape(SlidesApp.ShapeType.RECTANGLE, 100, 150, 100, 100);
  rectangle.getFill().setSolidFill('#FF9900'); // 주황색 채우기

  // 도형에 텍스트 추가
  var triangleText = slide.insertShape(SlidesApp.ShapeType.TRIANGLE, 250, 150, 100, 100);
  triangleText.getText().setText('도형 안의 텍스트');
  triangleText.getFill().setSolidFill('#9900CC'); // 보라색 채우기

  Logger.log('다양한 도형들이 추가되었습니다.');
}

/**
 * 이미지 URL에서 이미지 삽입하기 (URL 접근 가능한 이미지만 가능)
 */
function insertImageFromUrl() {
  var slide = SlidesApp.getActivePresentation().getSelection().getCurrentPage();
  if (!slide) {
    slide = SlidesApp.getActivePresentation().getSlides()[0];
  }

  // 이미지 URL (실제 작동하는 이미지 URL로 교체해야 함)
  var imageUrl = 'https://www.google.com/images/branding/googlelogo/2x/googlelogo_color_272x92dp.png';

  try {
    // 이미지 삽입
    var image = slide.insertImage(imageUrl);

    // 이미지 크기 조정
    image.setWidth(200);
    image.setHeight(100);

    // 이미지 위치 설정
    image.setLeft(250);
    image.setTop(300);

    Logger.log('이미지가 삽입되었습니다.');
  } catch (e) {
    Logger.log('이미지 삽입 실패: ' + e.toString());
  }
}

// 4. 슬라이드 서식 관리

/**
 * 슬라이드 배경색 변경하기
 */
function changeSlideBackground() {
  var slide = SlidesApp.getActivePresentation().getSelection().getCurrentPage();
  if (!slide) {
    slide = SlidesApp.getActivePresentation().getSlides()[0];
  }

  // 단색 배경으로 변경
  slide.getBackground().setSolidFill('#E6F2FF'); // 연한 파란색

  Logger.log('슬라이드 배경색이 변경되었습니다.');
}

/**
 * 모든 제목 텍스트 스타일 변경하기
 */
function changeTitleTextStyles() {
  var presentation = SlidesApp.getActivePresentation();
  var slides = presentation.getSlides();

  for (var i = 0; i < slides.length; i++) {
    // 각 슬라이드의 모든 도형을 가져옵니다
    var shapes = slides[i].getShapes();

    // 각 도형을 반복하며 제목 placeholder를 찾습니다
    for (var j = 0; j < shapes.length; j++) {
      var shape = shapes[j];

      // placeholder 타입이 TITLE인 경우 스타일을 변경합니다
      if (shape.getPlaceholderType && shape.getPlaceholderType() === SlidesApp.PlaceholderType.TITLE) {
        var textRange = shape.getText();
        var textStyle = textRange.getTextStyle();

        // 스타일 설정
        textStyle.setFontFamily('Arial');
        textStyle.setFontSize(24);
        textStyle.setForegroundColor('#0066CC'); // 진한 파란색
        textStyle.setBold(true);

        // 로그 출력
        Logger.log('슬라이드 #' + (i+1) + '의 제목 스타일이 변경되었습니다.');
      }
    }
  }

  Logger.log('모든 슬라이드의 제목 스타일 변경 작업이 완료되었습니다.');
}

/**
 * 레이아웃 변경하기 - 새 슬라이드로 대체하는 방식
 */
function changeSlideLayout() {
  var presentation = SlidesApp.getActivePresentation();

  // 현재 선택된 슬라이드 가져오기
  var selection = presentation.getSelection();
  var currentPage = selection ? selection.getCurrentPage() : null;
  var slide = currentPage || presentation.getSlides()[0];

  // 현재 슬라이드의 내용 저장 (제목과 본문 텍스트)
  var titleText = "";
  var bodyText = "";

  var shapes = slide.getShapes();
  for (var i = 0; i < shapes.length; i++) {
    if (shapes[i].getText && shapes[i].getPlaceholderType) {
      var type = shapes[i].getPlaceholderType();
      var text = shapes[i].getText().asString();

      if (type === SlidesApp.PlaceholderType.TITLE) {
        titleText = text;
      } else if (type === SlidesApp.PlaceholderType.BODY) {
        bodyText = text;
      }
    }
  }

  // 새 슬라이드 생성 (원하는 레이아웃 적용)
  var newSlide = presentation.appendSlide(SlidesApp.PredefinedLayout.TITLE_AND_TWO_COLUMNS);

  // 저장된 내용을 새 슬라이드에 적용
  var newShapes = newSlide.getShapes();
  for (var i = 0; i < newShapes.length; i++) {
    if (newShapes[i].getText && newShapes[i].getPlaceholderType) {
      var type = newShapes[i].getPlaceholderType();

      if (type === SlidesApp.PlaceholderType.TITLE && titleText) {
        newShapes[i].getText().setText(titleText);
      } else if (type === SlidesApp.PlaceholderType.BODY && bodyText) {
        newShapes[i].getText().setText(bodyText);
      }
    }
  }

  Logger.log('새 레이아웃으로 슬라이드가 추가되었습니다.');
  Logger.log('참고: 기존 슬라이드는 유지됩니다. 필요 없는 경우 수동으로 삭제해 주세요.');
}

// 5. 자동화 기능 구현

/**
 * 사용자 정의 메뉴 추가
 */
function onOpen() {
  var ui = SlidesApp.getUi();

  // 사용자 정의 메뉴 생성
  ui.createMenu('Apps Script 도구')
    .addItem('새 슬라이드 생성', 'createNewSlide')
    .addItem('텍스트 상자 추가', 'createAndEditTextbox')
    .addItem('도형 추가', 'addAndManipulateShape')
    .addSeparator()
    .addSubMenu(ui.createMenu('서식')
      .addItem('배경색 변경', 'changeSlideBackground')
      .addItem('제목 스타일 변경', 'changeTitleTextStyles'))
    .addSeparator()
    .addItem('자동 슬라이드 생성', 'createSlidesFromTemplate')
    .addToUi();
}

/**
 * 1분마다 새 슬라이드를 추가하는 트리거 설정
 */
function createAutoSlideAddTrigger() {
  // 기존 트리거 삭제 (중복 방지)
  deleteExistingTriggers();

  // 1분마다 addNewSlideAutomatically 함수를 실행하는 트리거 생성
  ScriptApp.newTrigger('addNewSlideAutomatically')
    .timeBased()
    .everyMinutes(1)
    .create();

  Logger.log('매 1분마다 새 슬라이드를 추가하는 트리거가 설정되었습니다.');
}

/**
 * 기존 트리거 모두 삭제
 */
function deleteExistingTriggers() {
  var triggers = ScriptApp.getProjectTriggers();
  for (var i = 0; i < triggers.length; i++) {
    ScriptApp.deleteTrigger(triggers[i]);
  }
  Logger.log('기존 트리거가 모두 삭제되었습니다.');
}

/**
 * 자동으로 새 슬라이드 추가하는 함수
 * (트리거에 의해 실행됨)
 */
function addNewSlideAutomatically() {
  var presentation = SlidesApp.getActivePresentation();

  // 현재 시간 정보 가져오기
  var now = new Date();
  var timeString = now.toLocaleTimeString();
  var dateString = now.toLocaleDateString();

  // 새 슬라이드 추가
  var slide = presentation.appendSlide(SlidesApp.PredefinedLayout.TITLE_AND_BODY);

  // 슬라이드에 텍스트 추가 (모든 슬라이드 요소 순회)
  var shapes = slide.getShapes();
  for (var i = 0; i < shapes.length; i++) {
    if (shapes[i].getText && shapes[i].getPlaceholderType) {
      var type = shapes[i].getPlaceholderType();

      if (type === SlidesApp.PlaceholderType.TITLE) {
        // 제목에 날짜와 시간 표시
        shapes[i].getText().setText('자동 생성된 슬라이드 - ' + dateString);
      } else if (type === SlidesApp.PlaceholderType.BODY) {
        // 본문에 시간과 슬라이드 정보 표시
        shapes[i].getText().setText(
          '이 슬라이드는 ' + timeString + '에 자동으로 생성되었습니다.\n\n' + 
          '현재 슬라이드 수: ' + presentation.getSlides().length + '\n' +
          '트리거로 생성된 슬라이드입니다.'
        );
      }
    }
  }

  // 로그 기록
  Logger.log('새 슬라이드가 자동으로 추가되었습니다: ' + timeString);
}

/**
 * 현재 트리거 목록 확인
 */
function listAllTriggers() {
  var triggers = ScriptApp.getProjectTriggers();

  if (triggers.length === 0) {
    Logger.log('설정된 트리거가 없습니다.');
    return;
  }

  Logger.log('현재 설정된 트리거 목록:');
  for (var i = 0; i < triggers.length; i++) {
    var trigger = triggers[i];
    Logger.log('트리거 #' + (i + 1));
    Logger.log('  - 실행 함수: ' + trigger.getHandlerFunction());
    Logger.log('  - 이벤트 유형: ' + trigger.getEventType());
  }
}
